using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api")][Authorize] public class CrmApiController(ApplicationDbContext db,AuditService audit):ControllerBase{
 string? UserId=>User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value; bool Broad=>User.IsInRole("Admin")||User.IsInRole("Manager");
 [HttpGet("customers")]public async Task<IActionResult>Customers([FromQuery]string? q){var x=db.Customers.AsQueryable();if(!Broad)x=x.Where(a=>a.OwnerId==UserId);if(!string.IsNullOrWhiteSpace(q))x=x.Where(a=>a.Name.Contains(q)|| (a.Email??"").Contains(q));return Ok(await x.Select(a=>new{id=a.Id,a.Name,a.Email,a.Phone,a.Status,a.OwnerId,a.CreatedAt}).ToListAsync());}
 [HttpPost("customers")]public async Task<IActionResult>CreateCustomer(CustomerDto d){if(!ModelState.IsValid)return ValidationProblem(ModelState);var x=new Customer{Name=d.Name,Email=d.Email,Phone=d.Phone,Address=d.Address,OwnerId=UserId};db.Customers.Add(x);await db.SaveChangesAsync();await audit.WriteAsync(User,"Customers","ApiCreate",x.Id.ToString(),x.Name);return Created($"/api/customers/{x.Id}",new{id=x.Id,x.Name,x.Email,x.Phone,x.Status});}
 [HttpGet("customers/{id:int}")]public async Task<IActionResult>Customer(int id){var x=await db.Customers.FindAsync(id);if(x==null)return NotFound();if(!Broad&&x.OwnerId!=UserId)return Forbid();return Ok(new{id=x.Id,x.Name,x.Email,x.Phone,x.Address,x.Status});}
 [HttpGet("leads")]public async Task<IActionResult>Leads(){var x=db.Leads.AsQueryable();if(!Broad)x=x.Where(a=>a.OwnerId==UserId);return Ok(await x.Select(a=>new{id=a.Id,a.Name,a.Email,a.Phone,a.Source,a.Status,a.Priority}).ToListAsync());}
 [HttpPost("leads")]public async Task<IActionResult>CreateLead(LeadDto d){if(!ModelState.IsValid)return ValidationProblem(ModelState);var x=new Lead{Name=d.Name,Email=d.Email,Phone=d.Phone,Source=d.Source??"Website",OwnerId=UserId};db.Leads.Add(x);await db.SaveChangesAsync();await audit.WriteAsync(User,"Leads","ApiCreate",x.Id.ToString(),x.Name);return Created($"/api/leads/{x.Id}",new{id=x.Id,x.Name,x.Status});}
 [HttpGet("opportunities")]public async Task<IActionResult>Opportunities(){var x=db.Opportunities.Include(a=>a.Customer).AsQueryable();if(!Broad)x=x.Where(a=>a.OwnerId==UserId);return Ok(await x.Select(a=>new{id=a.Id,a.Name,Customer=a.Customer!.Name,a.Stage,a.Amount,a.Probability,Weighted=a.Amount*a.Probability/100m,a.ExpectedCloseDate}).ToListAsync());}
 [HttpPost("opportunities")]public async Task<IActionResult>CreateOpportunity(OpportunityDto d){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(d.Amount<=0)return BadRequest(new{error="Opportunity Amount must be greater than 0."});if(d.ExpectedCloseDate.Date<DateTime.Today)return BadRequest(new{error="Expected Close Date cannot be in the past."});var customer=await db.Customers.FirstOrDefaultAsync(x=>x.Id==d.CustomerId);
 if(customer==null)return BadRequest(new{error="Customer not found."});
 if(!Broad&&customer.OwnerId!=UserId)return Forbid();var x=new Opportunity{Name=d.Name,CustomerId=d.CustomerId,Amount=d.Amount,Probability=d.Probability,ExpectedCloseDate=d.ExpectedCloseDate,OwnerId=UserId};db.Opportunities.Add(x);await db.SaveChangesAsync();await audit.WriteAsync(User,"Opportunities","ApiCreate",x.Id.ToString(),x.Name);return Created($"/api/opportunities/{x.Id}",new{id=x.Id,x.Name,x.Amount,x.Probability});}
 [HttpGet("followups")]public async Task<IActionResult>Followups(){var x=db.FollowUps.AsQueryable();if(!Broad)x=x.Where(a=>a.AssignedUserId==UserId);return Ok(await x.Select(a=>new{id=a.Id,a.Subject,a.FollowUpDate,a.Status,a.RelatedType,a.RelatedId}).ToListAsync());}
 [HttpPost("followups")]public async Task<IActionResult>CreateFollowup(FollowUpDto d){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(d.FollowUpDate.Date<DateTime.Today)return BadRequest(new{error="Follow-up date cannot be earlier than today."});
 var relatedType=string.IsNullOrWhiteSpace(d.RelatedType)?"Customer":d.RelatedType.Trim();
 if(relatedType=="Customer"&&d.RelatedId.HasValue){var related=await db.Customers.FirstOrDefaultAsync(c=>c.Id==d.RelatedId.Value);if(related==null)return BadRequest(new{error="Related customer not found."});if(!Broad&&related.OwnerId!=UserId)return Forbid();}
 else if(relatedType=="Lead"&&d.RelatedId.HasValue){var related=await db.Leads.FirstOrDefaultAsync(l=>l.Id==d.RelatedId.Value);if(related==null)return BadRequest(new{error="Related lead not found."});if(!Broad&&related.OwnerId!=UserId)return Forbid();}
 else if(relatedType!="Customer"&&relatedType!="Lead")return BadRequest(new{error="RelatedType must be Customer or Lead."});
 var x=new FollowUp{Subject=d.Subject,FollowUpDate=d.FollowUpDate,RelatedType=relatedType,RelatedId=d.RelatedId,AssignedUserId=UserId};db.FollowUps.Add(x);await db.SaveChangesAsync();await audit.WriteAsync(User,"FollowUps","ApiCreate",x.Id.ToString(),x.Subject);return Created($"/api/followups/{x.Id}",new{id=x.Id,x.Subject,x.FollowUpDate,x.Status});}
 [HttpGet("reports/pipeline"),Authorize(Roles="Admin,Manager")]public async Task<IActionResult>Pipeline()=>Ok(await db.Opportunities.GroupBy(x=>x.Stage).Select(g=>new{stage=g.Key,amount=g.Sum(x=>x.Amount),weighted=g.Sum(x=>x.Amount*x.Probability/100m)}).ToListAsync());
}
public record CustomerDto([System.ComponentModel.DataAnnotations.Required]string Name,[System.ComponentModel.DataAnnotations.EmailAddress]string? Email,string? Phone,string? Address);
public record LeadDto([System.ComponentModel.DataAnnotations.Required]string Name,[System.ComponentModel.DataAnnotations.EmailAddress]string? Email,string? Phone,string? Source);
public record OpportunityDto([System.ComponentModel.DataAnnotations.Required]string Name,int CustomerId,decimal Amount,[System.ComponentModel.DataAnnotations.Range(0,100)]int Probability,DateTime ExpectedCloseDate);
public record FollowUpDto([System.ComponentModel.DataAnnotations.Required]string Subject,DateTime FollowUpDate,string? RelatedType,int? RelatedId);
